    <style>
        @import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700&display=swap');
        :root{--p:{{ $palette['primary'] }};--a:{{ $palette['accent'] }};--s:{{ $palette['surface'] }};--t:{{ $palette['text'] }};--m:{{ $palette['muted'] }};--b:{{ $palette['border'] }};--bg:{{ $palette['background'] }}}
        *{box-sizing:border-box}body{margin:0;background:linear-gradient(180deg,var(--bg),color-mix(in srgb,var(--p) 4%,var(--bg)));color:var(--t);font-family:Manrope,system-ui,sans-serif}.wrap{width:min(1180px,calc(100% - 40px));margin:auto}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}.shell{background:var(--bg)}
        .fallback-header{border-bottom:1px solid var(--b);background:color-mix(in srgb,var(--bg) 94%,transparent);backdrop-filter:blur(12px)}.fallback-header .wrap{display:flex;justify-content:space-between;align-items:center;padding:18px 0}.brand{font-weight:700}.fallback-header nav{display:flex;gap:20px;font-size:14px}.fallback-footer{margin-top:72px;background:color-mix(in srgb,var(--p) 9%,#0f172a);color:#e2e8f0;padding:34px 0}.fallback-footer .wrap{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}
        .content-hero{padding:72px 0 48px;border-bottom:1px solid var(--b);background:linear-gradient(135deg,color-mix(in srgb,var(--p) 14%,var(--bg)),var(--bg) 66%)}.kicker{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.22em;color:var(--p)}h1,h2,h3{font-weight:700;letter-spacing:-.035em}h1{font-size:clamp(40px,6vw,68px);line-height:1.02;margin:14px 0}.hero-copy{max-width:720px;color:var(--m);font-size:17px;line-height:1.75}.filters{display:flex;gap:10px;flex-wrap:wrap;margin-top:28px}.pill{display:inline-flex;align-items:center;min-height:38px;padding:8px 13px;border:1px solid var(--b);border-radius:999px;background:var(--bg);font-size:13px;font-weight:600}.pill.active{background:var(--p);border-color:var(--p);color:white}
        .archive{padding:44px 0 72px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.card{overflow:hidden;border:1px solid var(--b);border-radius:24px;background:var(--bg);box-shadow:0 16px 45px rgba(15,23,42,.055);transition:.2s}.card:hover{transform:translateY(-3px);box-shadow:0 22px 56px rgba(15,23,42,.09)}.card-media{aspect-ratio:16/10;background:var(--s);overflow:hidden}.card-media img{width:100%;height:100%;object-fit:cover}.card-body{padding:22px}.meta{font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.15em;color:var(--p)}.card h2{font-size:22px;line-height:1.18;margin:10px 0}.card p{color:var(--m);font-size:14px;line-height:1.65}.read{display:inline-flex;margin-top:14px;font-size:14px;font-weight:700}.empty{padding:48px;text-align:center;border:1px dashed var(--b);border-radius:24px;color:var(--m)}
        .entry{padding:44px 0 72px}.breadcrumb{display:flex;gap:9px;align-items:center;font-size:13px;color:var(--m);margin-bottom:30px}.entry-head{max-width:880px;margin-bottom:28px}.entry-head h1{font-size:clamp(42px,6vw,72px)}.entry-deck{font-size:19px;line-height:1.7;color:var(--m);max-width:760px}.entry-meta{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px;color:var(--m);font-size:13px}.hero-image{overflow:hidden;border:1px solid var(--b);border-radius:30px;background:var(--s);box-shadow:0 24px 70px rgba(15,23,42,.09);margin:32px 0}.hero-image img{width:100%;max-height:680px;object-fit:cover}.entry-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:54px;align-items:start}.prose{font-size:17px;line-height:1.85;color:color-mix(in srgb,var(--t) 84%,var(--m))}.prose p{margin:0 0 1.35em}.prose h2,.prose h3{color:var(--t);margin:1.7em 0 .65em}.sidebar{position:sticky;top:24px}.info-card{border:1px solid var(--b);border-radius:22px;background:var(--bg);padding:20px;box-shadow:0 12px 36px rgba(15,23,42,.045)}.info-row{padding:11px 0;border-bottom:1px solid var(--b)}.info-row:last-child{border-bottom:0}.info-label{font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.15em;color:var(--m)}.info-value{margin-top:4px;font-size:14px;font-weight:600}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-top:34px}.gallery img{width:100%;height:190px;object-fit:cover;border:1px solid var(--b);border-radius:18px}.related{padding:64px 0;border-top:1px solid var(--b)}.related h2{font-size:34px;margin:0 0 26px}.related .grid{grid-template-columns:repeat(3,minmax(0,1fr))}
        @media(max-width:900px){.grid,.related .grid{grid-template-columns:repeat(2,minmax(0,1fr))}.entry-layout{grid-template-columns:1fr}.sidebar{position:static}.gallery{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.wrap{width:min(100% - 24px,1180px)}.content-hero{padding:50px 0 34px}.archive,.entry{padding-top:30px}.grid,.related .grid{grid-template-columns:1fr}.entry-head h1{font-size:40px}.gallery{grid-template-columns:1fr}.gallery img{height:auto}.fallback-header nav{display:none}}
    </style>
</head>
