@if($viewMode === 'archive')
<section class="content-hero"><div class="wrap"><div class="kicker">{{ $contentType->singular_name }} archive</div><h1>{{ $contentType->name }}</h1><p class="hero-copy">{{ $contentType->description ?: 'Explore the latest '.$contentType->name.'.' }}</p>@if($categories->isNotEmpty() || $tags->isNotEmpty())<div class="filters"><a class="pill {{ !$activeCategory && !$activeTag ? 'active' : '' }}" href="{{ $archiveUrl($contentType) }}">All</a>@foreach($categories as $category)<a class="pill {{ $activeCategory === $category ? 'active' : '' }}" href="{{ $archiveUrl($contentType) }}?category={{ rawurlencode($category) }}">{{ $category }}</a>@endforeach @foreach($tags->take(6) as $tag)<a class="pill {{ $activeTag === $tag ? 'active' : '' }}" href="{{ $archiveUrl($contentType) }}?tag={{ rawurlencode($tag) }}">#{{ $tag }}</a>@endforeach</div>@endif</div></section>
<section class="archive"><div class="wrap">@if($entries->isEmpty())<div class="empty">No published {{ strtolower($contentType->name) }} yet.</div>@else<div class="grid">@foreach($entries as $entry)<article class="card"><a class="card-media" href="{{ $entryUrl($contentType,$entry) }}">@if($entry->featured_image_url)<img src="{{ $assetUrl($entry->featured_image_url) }}" alt="{{ $entry->title }}">@endif</a><div class="card-body"><div class="meta">{{ $entry->category ?: $contentType->singular_name }}@if($entry->is_featured) · Featured @endif</div><h2><a href="{{ $entryUrl($contentType,$entry) }}">{{ $entry->title }}</a></h2><p>{{ $entry->excerpt }}</p><a class="read" href="{{ $entryUrl($contentType,$entry) }}">Read more →</a></div></article>@endforeach</div>@endif</div></section>
@else
<section class="entry"><div class="wrap"><div class="breadcrumb"><a href="{{ $archiveUrl($contentType) }}">{{ $contentType->name }}</a><span>›</span><span>{{ $activeEntry->title }}</span></div><header class="entry-head"><div class="kicker">{{ $activeEntry->category ?: $contentType->singular_name }}@if($activeEntry->is_featured) · Featured @endif</div><h1>{{ $activeEntry->title }}</h1>@if($activeEntry->excerpt)<p class="entry-deck">{{ $activeEntry->excerpt }}</p>@endif<div class="entry-meta">@if($activeEntry->published_at)<span>{{ $activeEntry->published_at->format('M j, Y') }}</span>@endif @foreach(($activeEntry->tags ?: []) as $tag)<span>#{{ $tag }}</span>@endforeach</div></header>@if($activeEntry->featured_image_url)<div class="hero-image"><img src="{{ $assetUrl($activeEntry->featured_image_url) }}" alt="{{ $activeEntry->title }}"></div>@endif<div class="entry-layout"><article class="prose">{!! nl2br(e($activeEntry->content ?: $activeEntry->excerpt)) !!}@if(is_array($activeEntry->gallery) && count($activeEntry->gallery))<div class="gallery">@foreach($activeEntry->gallery as $item)@php($src=is_array($item)?($item['url']??$item['src']??''):$item)@if($src)<img src="{{ $assetUrl($src) }}" alt="{{ is_array($item)?($item['alt']??$activeEntry->title):$activeEntry->title }}">@endif @endforeach</div>@endif</article><aside class="sidebar"><div class="info-card"><div class="meta">{{ $contentType->singular_name }} details</div>@if($activeEntry->category)<div class="info-row"><div class="info-label">Category</div><div class="info-value">{{ $activeEntry->category }}</div></div>@endif @foreach(($contentType->schema ?: []) as $field)@php($value=data_get($activeEntry->custom_fields ?: [],$field['key']??''))@if($value !== null && $value !== '' && $value !== false)<div class="info-row"><div class="info-label">{{ $field['label'] ?? $field['key'] ?? 'Detail' }}</div><div class="info-value">@if(($field['type']??'')==='url')<a href="{{ $value }}" target="_blank" rel="noopener">Open link ↗</a>@elseif(($field['type']??'')==='date'){{ \Illuminate\Support\Carbon::parse($value)->format('M j, Y') }}@elseif(($field['type']??'')==='boolean'){{ $value ? 'Yes' : 'No' }}@else{{ $value }}@endif</div></div>@endif @endforeach</div></aside></div></div></section>
@if($relatedEntries->isNotEmpty())<section class="related"><div class="wrap"><div class="kicker">Keep exploring</div><h2>Related {{ strtolower($contentType->name) }}</h2><div class="grid">@foreach($relatedEntries as $entry)<article class="card"><a class="card-media" href="{{ $entryUrl($contentType,$entry) }}">@if($entry->featured_image_url)<img src="{{ $assetUrl($entry->featured_image_url) }}" alt="{{ $entry->title }}">@endif</a><div class="card-body"><div class="meta">{{ $entry->category ?: $contentType->singular_name }}</div><h3><a href="{{ $entryUrl($contentType,$entry) }}">{{ $entry->title }}</a></h3><p>{{ $entry->excerpt }}</p><a class="read" href="{{ $entryUrl($contentType,$entry) }}">Read next →</a></div></article>@endforeach</div></div></section>@endif
